// REQ: MFCONN-03, MFRECOVERY-01
TEST_F(AcmpCore, ReviewerSteppedAdpTimeout) {
    bind(0);
    adp(Adp{});
    const std::uint32_t deadline = a.sinks[0].adp_deadline;
    unsigned probes = 0;
    while (a.sinks[0].adp_armed && fk.now - 50000u < 30000u) {
        fk.clear();
        fk.now += 50u;
        acmp_timer_expired(&a, 0);
        probes += static_cast<unsigned>(fk.sent.size());
    }
    EXPECT_TRUE(fk.now >= deadline && fk.now < deadline + 50u) << "reviewer stepped expiry occurs at the deadline";
    EXPECT_TRUE(probes >= 2u) << "reviewer stepped retries are sent before expiry";
    const auto v = view(0);
    EXPECT_TRUE(v.bound && v.binding.talker_entity_id == kTkA && v.binding.controller_entity_id == kCtl1 &&
                v.state == ACMP_PRB_W_AVAIL && !a.sinks[0].discovered) << "reviewer stepped expiry retains the binding";
    fk.clear();
    Adp back;
    back.index = 2;
    adp(back);
    fire(0);
    ASSERT_EQ(fk.sent.size(), 1u) << "reviewer stepped rediscovery sends one probe";
    EXPECT_TRUE(last().msg == spec::MSG_PROBE_TX_COMMAND && last().talker == kTkA && view(0).bound)
        << "reviewer stepped rediscovery probes the retained binding";
}

